import type { Concept, Difficulty, Mode, Question, QuestionType, StructuredField } from "@/lib/model";

const frameworkVersion = "16.4.3";
const cacheVersionNotes =
  "Assumes Next.js 16.4.3 App Router with cacheComponents: true and partialPrefetching: true, matching next.config.ts. Request APIs are async; cached and request-time regions may coexist. Do not apply legacy route-segment caching defaults.";

const select = (id: string, label: string, options: string[], correct: string[], multiple = false,
  misconceptionTag?: string, severity?: "critical"): StructuredField => ({
  id, label, kind: "select", choices: options.map((choice) => ({ id: choice, label: choice })),
  correct, multiple, misconceptionTag, severity,
});
const one = (id: string, label: string, options: string[], correct: string, tag?: string,
  severity?: "critical") => select(id, label, options, [correct], false, tag, severity);
const officialReferences: Partial<Record<Concept, string>> = {
  nextRouting: "https://nextjs.org/docs/app/getting-started/layouts-and-pages",
  nextBoundaries: "https://nextjs.org/docs/app/getting-started/server-and-client-components",
  nextDataFetching: "https://nextjs.org/docs/app/getting-started/fetching-data",
  nextRendering: "https://nextjs.org/docs/app/getting-started/caching",
  nextCaching: "https://nextjs.org/docs/app/getting-started/revalidating",
  nextDataBoundaries: "https://nextjs.org/docs/app/getting-started/route-handlers",
  nextMutations: "https://nextjs.org/docs/app/getting-started/mutating-data",
};

function exercise(id: string, mode: Mode, type: QuestionType, concepts: Concept[], difficulty: Difficulty,
  prompt: string, fields: StructuredField[], explanation: string, options: {
    code?: string;
    depth?: "core" | "optional";
    readinessDimensions?: string[];
    versionSensitive?: boolean;
    versionNotes?: string;
  } = {}): Question {
  const versionSensitive = options.versionSensitive ?? (
    concepts.some((concept) => officialReferences[concept]) ||
    /use cache|cacheLife|cacheTag|revalidatePath|revalidateTag|updateTag|router\.refresh|cookies\(\)|headers\(\)/.test(`${prompt}\n${options.code ?? ""}\n${explanation}`)
  );
  const dimensionByConcept: Partial<Record<Concept, string[]>> = {
    nextBoundaries: ["boundaries"], nextDataFetching: ["fetching"], nextCaching: ["caching"],
    nextPdp: ["pdp"], nextMutations: ["mutations"], nextPerformance: ["performance"],
    nextArchitecture: ["large-app"],
  };
  const dimensions = concepts.flatMap((concept) => dimensionByConcept[concept] ?? []);
  const balancedFields = fields.map((field, index) => {
    if (field.kind !== "select") return field;
    const offset = [...id].reduce((sum, char) => sum + char.charCodeAt(0), index) % field.choices.length;
    return { ...field, choices: [...field.choices.slice(offset), ...field.choices.slice(0, offset)] };
  });
  return {
    id: `nextfa-${id}`,
    module: "nextjs-frontend-architecture",
    mode,
    concepts,
    difficulty,
    prompt: versionSensitive ? `Next.js ${frameworkVersion}, Cache Components enabled: ${prompt}` : prompt,
    code: options.code,
    structured: { type, fields: balancedFields },
    depth: options.depth ?? "core",
    frameworkVersion,
    versionSensitive,
    versionNotes: versionSensitive ? options.versionNotes ?? cacheVersionNotes : undefined,
    reference: /retry|error boundary|error\.tsx/.test(`${prompt} ${explanation}`)
      ? "https://nextjs.org/docs/app/api-reference/file-conventions/error"
      : concepts.map((concept) => officialReferences[concept]).find(Boolean) ??
        (versionSensitive ? "https://nextjs.org/docs/app/getting-started/caching" : undefined),
    readinessDimensions: [...new Set([
      ...(mode === "architecture" ? ["architecture"] : []),
      ...(mode !== "reconstruction" ? dimensions : []),
      ...(options.readinessDimensions ?? []),
    ])],
    answer: fields.map((field) =>
      `${field.label}: ${field.kind === "text" ? field.accepted[0] : field.correct.join(", ")}`).join("\n"),
    explanation,
    misconception: { prompt: `Reconstruct the decision you missed: ${prompt}`, answer: explanation },
  };
}

