type Choices = [string, string, string];

function decision(id: string, mode: Mode, concept: Concept | Concept[], difficulty: Difficulty,
  prompt: string, choices: Choices, explanation: string, tag: string, code?: string,
  dimensions?: string[], depth: "core" | "optional" = "core"): Question {
  return exercise(id, mode, mode === "prediction" ? "prediction" : "bestExplanation",
    Array.isArray(concept) ? concept : [concept], difficulty, prompt,
    [one("decision", "Best supported decision", choices, choices[0], tag, difficulty === "hard" ? "critical" : undefined)],
    explanation, { code, readinessDimensions: dimensions, depth });
}

function bug(id: string, concept: Concept | Concept[], difficulty: Difficulty, prompt: string,
  code: string, roots: Choices, fixes: Choices, explanation: string, tag: string): Question {
  return exercise(id, "debug", "debug", Array.isArray(concept) ? concept : [concept], difficulty, prompt,
    [one("root", "Root cause", roots, roots[0], tag),
      one("fix", "Smallest good fix", fixes, fixes[0], tag, "critical")],
    explanation, { code });
}

